    for i in range(1 << n):
        config = []
        for j in range(n):
            if (i >> j) & 1:
                config.append(1)
            else:
                config.append(0)

        current_config = list(config)
        turns = 0
        while sum(current_config) > 0:
            k = sum(current_config)
            current_config[k-1] = 1 - current_config[k-1]
            turns += 1
